use vstd::prelude::*;

verus! {
    /// Deep‐clone a Vec<u64> by allocating a fresh Vec and pushing element by element.
    ///
    /// Ensures that the clone has exactly the same length as the original
    /// and that every element at index i is equal.
    fn list_deep_clone(arr: &Vec<u64>) -> (copied: Vec<u64>)
        ensures
            // same length
            copied.len() == arr.len(),
            // same contents
            forall |i: nat| i < arr.len() as nat ==> copied[i] == arr[i],
    {
        // Pre‐allocate with the same capacity as arr.len()
        let mut copied = Vec::with_capacity(arr.len());

        // Copy each element
        for &value in arr.iter() {
            copied.push(value);
        }

        // Return the fresh clone
        copied
    }
}

